using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SingularitySextantOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SingularitySextant Omen Data")]
public class SingularitySextantOmenData : OmenData
{
	[NonSerialized]
	private Func<bool> omenAction;

	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		omenAction = delegate
		{
			if (!AlreadyUsed)
			{
				omenInstance.ActivateOmenFeedback();
				ToggleAlreadyUsed(toggle: true);
				return true;
			}
			return false;
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.SingularitySextantAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.SingularitySextantAction = null;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
	}

	public override string OmenConvertedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedFirstDrawPhaseEachBattle(withSpace: true) + base.OmenConvertedDescription();
	}
}
